<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\DataImport;use App\Services\Import\CsvTemplateService;use Illuminate\Http\Request;use Maatwebsite\Excel\Facades\Excel;
class DataImportCentreController extends Controller {public function index(){return view('admin.imports.index',['imports'=>DataImport::latest()->paginate(30),'modules'=>['appraisal_kras','appraisal_kpis','employees','mentorship','jobs_tracking']]);} public function template(string $m,CsvTemplateService $s){return response($s->csv($m),200,['Content-Type'=>'text/csv; charset=UTF-8','Content-Disposition'=>'attachment; filename=\"'.$m.'_template.csv\"']);} public function upload(Request $r){$d=$r->validate(['module'=>'required|in:appraisal_kras,appraisal_kpis,employees,mentorship,jobs_tracking','file'=>'required|file|mimes:csv,txt,xls,xlsx|max:10240']);$p=$r->file('file')->store('imports');$rows=Excel::toArray([],$r->file('file'))[0]??[];$header=array_map(fn($v)=>trim((string)$v),array_shift($rows)??[]);$i=DataImport::create(['module'=>$d['module'],'original_filename'=>$r->file('file')->getClientOriginalName(),'stored_path'=>$p,'column_mapping'=>array_combine($header,$header)?:[],'total_rows'=>count($rows),'invalid_rows'=>count($rows),'status'=>'preview','uploaded_by'=>auth()->id()]);return redirect()->route('admin.import-centre.preview',$i);} public function preview(DataImport $dataImport){$rows=Excel::toArray([],storage_path('app/'.$dataImport->stored_path))[0]??[];$headers=array_map(fn($v)=>trim((string)$v),array_shift($rows)??[]);return view('admin.imports.preview',['import'=>$dataImport,'headers'=>$headers,'rows'=>array_slice($rows,0,25)]);}}
